"""
Contract the leading and collinear operators against the dipole-chain state.

The chain state factorizes into adjacent dipoles, as in Eq. (3). Return the elementary-dipole projections of K0|S) and L|S), with the real and virtual terms of Eqs. (7) and (13).

Returns
-------
return result  # ndarray, shape (2,n,n), dimensionless, ordered [K0 action, L action].
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def dipole_fields(s: "np.ndarray", one: "np.ndarray") -> "np.ndarray":
    """s : ndarray, shape (n,n), dimensionless dipole values, row = first endpoint. Algebraic cases may be nonsymmetric.
    one : ndarray, shape (3,n,n,n), weighted single-emission kernels in emission_kernels order.
    
    Returns
    -------
    ndarray, shape (2,n,n), dimensionless, ordered [K0 action, L action].
    Inputs must be finite. Invalid dimensions, scales, or prescribed domains raise ValueError. 
    """
    return result

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np

def _state(s,one):
    import numpy as np
    s=np.asarray(s);one=np.asarray(one)
    if s.ndim!=2:raise ValueError('State must be a matrix.')
    n=len(s)
    if s.shape!=(n,n) or one.shape!=(3,n,n,n) or not np.all(np.isfinite(s)) or not np.all(np.isfinite(one)):
        raise ValueError('Incompatible state or emission kernels.')
    return s,one


def _oracle_dipole_fields(s: "np.ndarray", one: "np.ndarray") -> "np.ndarray":
    """Leibniz-projected LO and logarithmic rotation fields, Eqs. 9 and 14."""
    import numpy as np
    s,one=_state(s,one)
    return np.einsum('aijk,ik,kj->aij',one[:2],s,s)-s[None,:,:]*one[:2].sum(axis=3)

